func:
if (!msg.payload || typeof msg.payload !== 'object' || Array.isArray(msg.payload)) {
    node.warn('État technique Modbus invalide');
    return null;
}
flow.set('watchdogKitModbusState', msg.payload);
return null;

const state = flow.get('watchdogKitModbusState') || {};
const uuid = env.get('BALENA_DEVICE_UUID');
const name = env.get('BALENA_DEVICE_NAME_AT_INIT') || env.get('BALENA_DEVICE_NAME') || env.get('HOSTNAME');
if (!uuid || !name) {
    node.status({ fill: 'red', shape: 'ring', text: 'identité Balena absente' });
    return null;
}
const modbus = state.health && state.health.modbus;
const healthOk = Boolean(state.health && state.health.ok && modbus && modbus.ok);
msg.topic = 'bacnet/gateway/' + uuid + '/heartbeat';
msg.qos = 1;
msg.retain = true;
msg.payload = {
    schema: 'watchdog.heartbeat.v1',
    ts: Date.now(),
    device: { uuid, name, app: env.get('BALENA_APP_NAME') || '', host: env.get('HOSTNAME') || '', protocol: 'modbus' },
    health: Object.assign({ ok: healthOk, protocol: 'modbus', modbus: modbus || { ok: false, lastError: 'état Modbus absent' } }, state.health || {}, { protocol: 'modbus' }),
    mqtt: Object.assign({ ok: false, connected: false, status: 'unknown' }, state.mqtt || {}),
    buffer: Object.assign({ state: 'unknown', pending: 0 }, state.buffer || {}),
    snapshot: null,
    supervisor: state.supervisor === undefined ? null : state.supervisor
};
node.status({ fill: healthOk ? 'green' : 'red', shape: 'dot', text: healthOk ? 'ok' : 'dégradé' });
return msg;
